// topology.subgraph: The neighbourhood of one exchange or queue, at most two hops
// Generated by `pnpm nx g @app/generators:action topology.subgraph`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  GraphAnswerSchema,
  GraphFocusSchema,
  MaxElementsSchema,
  VhostNameSchema,
} from './topology-types.ts';

export const TopologySubgraphInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  vhost: VhostNameSchema,
  focus: GraphFocusSchema,
  /** Hops from the focus, 0 to 2 (default 1). */
  depth: z.union([z.literal(0), z.literal(1), z.literal(2)]).optional(),
  /** Nodes plus edges at most; default and ceiling 2,000. Past it the answer is aggregated. */
  maxElements: MaxElementsSchema.optional(),
  /** Read the broker again instead of using a snapshot taken in the last seconds. */
  refresh: z.boolean().optional(),
});

export const TopologySubgraphOutputSchema = GraphAnswerSchema;

export const topologySubgraph = defineAction({
  id: 'topology.subgraph',
  kind: 'query',
  summary:
    'The neighbourhood of one exchange or queue, at most two hops, held to a fixed number of elements',
  input: TopologySubgraphInputSchema,
  output: TopologySubgraphOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({
    connectionId: input.cid,
    vhost: input.vhost,
    kind: input.focus.kind,
    name: input.focus.name,
  }),
  http: { method: 'POST', path: '/connections/{cid}/topology/subgraphs' },
  mcp: {
    expose: true,
    mutating: false,
    title: 'Topology around an object',
    description:
      'The exchanges, queues and links within at most two hops of one exchange or queue, at most 2,000 elements; a larger neighbourhood is aggregated and says so.',
  },
  cli: { command: 'topology subgraph' },
  since: '1.0',
});
